solution.solution.cpp:
#include <cmath>

struct Point
{
    double x{};
    double y{};
};

double distance(const Point& a, const Point& b)
{
    const double dx{ b.x - a.x };
    const double dy{ b.y - a.y };
    return std::sqrt(dx * dx + dy * dy);
}

Point midpoint(const Point& a, const Point& b)
{
    return Point{ (a.x + b.x) / 2, (a.y + b.y) / 2 };
}

unitTests:
TEST("a 3-4-5 triangle") { CHECK_NEAR(distance(Point{ 1, 2 }, Point{ 4, 6 }), 5.0, 1e-9); }
TEST("distance to itself is zero") { CHECK_NEAR(distance(Point{ 7, 7 }, Point{ 7, 7 }), 0.0, 1e-12); }
TEST("midpoint") { const Point m{ midpoint(Point{ 1, 2 }, Point{ 4, 6 }) }; CHECK_NEAR(m.x, 2.5, 1e-12); CHECK_NEAR(m.y, 4.0, 1e-12); }

